<?php

declare(strict_types=1);

require_once __DIR__.'/legacy-migration/ChecklistTemplateAssociation.php';
function caseLinkEnv(string$n):string{$v=getenv($n);if(!is_string($v)||$v==='')throw new RuntimeException('CONFIGURATION_INVALID');return$v;}
set_exception_handler(static function(Throwable$e):never{$allowed=['OPERATIONAL_CASE_NOT_CLEAN','DEFINITION_VERSION_UNPROVEN','CHECKLIST_TEMPLATE_SNAPSHOT_MISMATCH','CHECKLIST_TEMPLATE_ASSOCIATION_CONFLICT'];$reason=in_array($e->getMessage(),$allowed,true)?$e->getMessage():'OPERATIONAL_CASE_TEMPLATE_LINK_UNAVAILABLE';echo json_encode(['ok'=>false,'reason'=>$reason],JSON_THROW_ON_ERROR),"\n";exit(2);});
$o=getopt('',['object-id:','template-snapshot-id:','effective-at:','apply']);$objectId=filter_var($o['object-id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$snapshotId=filter_var($o['template-snapshot-id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$effectiveAt=(string)($o['effective-at']??'');if($objectId===false||$snapshotId===false||$effectiveAt==='')throw new InvalidArgumentException('CONFIGURATION_INVALID');
$manifest=json_decode((string)file_get_contents(caseLinkEnv('FMONITOR_PILOT_ACTIVE_MANIFEST')),true,flags:JSON_THROW_ON_ERROR);$prefix=(string)($manifest['processPrefix']??'');$db=new mysqli(caseLinkEnv('FMONITOR_DB_HOST'),caseLinkEnv('FMONITOR_DB_USER'),caseLinkEnv('FMONITOR_DB_PASSWORD'),caseLinkEnv('FMONITOR_DB_NAME'),(int)caseLinkEnv('FMONITOR_DB_PORT'));$db->set_charset('utf8mb4');
$case=$db->query("SELECT c.id,c.process_state,p.source_cutoff_at,p.classification_version,p.category,p.classification_sha256 FROM `{$prefix}fm2_installation_cases` c JOIN `{$prefix}fm2_migration_classification_provenance` p ON p.output_kind='operational_case' AND p.output_id=c.id AND p.legacy_object_id=c.legacy_installation_object_id WHERE c.legacy_installation_object_id=".(int)$objectId." LIMIT 2")->fetch_all(MYSQLI_ASSOC);if(count($case)!==1||$case[0]['classification_version']!=='legacy-object-classification-v1'||$case[0]['category']!=='native_candidate'||preg_match('/^[a-f0-9]{64}$/D',(string)$case[0]['classification_sha256'])!==1)throw new DomainException('OPERATIONAL_CASE_NOT_CLEAN');
$template=$db->query("SELECT snapshot_version,valid_from,content_sha256 FROM `{$prefix}fm2_checklist_template_snapshots` WHERE id=".(int)$snapshotId)->fetch_assoc();if(!is_array($template))throw new DomainException('CHECKLIST_TEMPLATE_SNAPSHOT_MISMATCH');$notBefore=max((string)$template['valid_from'],(string)$case[0]['source_cutoff_at']);if($effectiveAt<$notBefore)throw new DomainException('DEFINITION_VERSION_UNPROVEN');
$policy=ChecklistTemplateAssociationPolicy::validate('operational_case',$effectiveAt,(string)$template['valid_from'],(string)$template['snapshot_version'],(string)$template['content_sha256']);if(!$policy['allowed'])throw new DomainException((string)$policy['conflictCode']);
$result=['ok'=>true,'mode'=>isset($o['apply'])?'apply':'dry-run','objectId'=>(int)$objectId,'caseId'=>(int)$case[0]['id'],'processState'=>$case[0]['process_state'],'effectiveAt'=>$effectiveAt,'notBefore'=>$notBefore,'templateSnapshotId'=>(int)$snapshotId,'templateSnapshotVersion'=>$template['snapshot_version'],'templateContentSha256'=>$template['content_sha256']];
if(isset($o['apply']))$result+=(new ChecklistTemplateAssociationTarget($db,$prefix))->associate('operational_case',(string)$case[0]['id'],$effectiveAt,(int)$snapshotId,(string)$template['content_sha256'],(string)$template['snapshot_version'],gmdate('Y-m-d H:i:s'));echo json_encode($result,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";
